//
//  TerminalActivityMonitor.swift
//  Xylem
//
//  Times of a terminal's recent output and input, and whether Claude
//  thinks it has focus, for ClaudeTabState.
//
//  Input comes from two places. Keystrokes (and Xylem's own `send(text:)`)
//  are noted by XylemTerminalView's key monitor and TerminalSession - in
//  SwiftTerm 1.99 they go straight to the process and never reach the
//  view's `send(source:data:)` (seen in a byte log). What does reach it
//  (`noteSent`) is generated by the terminal, and mostly isn't the user:
//
//  Claude Code turns on focus reporting (DECSET 1004), and SwiftTerm sends
//  the reports (`ESC [ I` / `ESC [ O`); they are recorded as focus
//  changes, not input - otherwise a tab switch would look like an answer
//  to a permission prompt.
//
//  The same goes for mouse reporting: Claude Code turns on any-motion
//  tracking (DECSET 1003, SGR 1006), so merely moving the pointer across a
//  tab's terminal sends a stream of reports. Motion and wheel reports are
//  not input (else hovering would clear "needs permission" and keep
//  Doctor's hook check waiting); button presses still are - a click can
//  pick an option in Claude's dialogs.
//
//  And for the terminal's own replies to Claude Code's queries at startup
//  (XTVERSION, kitty keyboard flags, DA, DECRPM, window size, OSC colour,
//  kitty graphics), which SwiftTerm also sends through `send` (seen in a
//  byte log): without this a claude still waiting at "trust this folder?"
//  looked typed-in from its first second.
//
//  A size change (window resize, a side panel shown or hidden) sends
//  SIGWINCH to every tab's program, background ones too, and Claude
//  redraws its whole screen - enough batches to look like a spinner after
//  a Stop. Output within `resizeWindow` of a resize is not counted.
//
//  SwiftTerm reports each output batch on its I/O thread
//  (`setProcessOutputHandler`), input arrives on main (key monitor,
//  `send(text:)`, `send(source:data:)`), and the view model reads a
//  snapshot on main - hence the lock. Recording is a timestamp in a small
//  ring, so the per-batch cost stays negligible.
//

import Foundation
import os

nonisolated final class TerminalActivityMonitor: Sendable {
    /// Output this soon after input is the echo of what was typed (Claude
    /// redraws its prompt box a little after each key; 0.35 s let typing
    /// read as "working" in the live app).
    static let echoWindow: TimeInterval = 1.0
    /// Output this soon after a terminal size change is the redraw.
    static let resizeWindow: TimeInterval = 1.0
    private static let capacity = 32

    private struct State {
        var lastInput: Date?
        var outputTimes: [Date] = []
        /// True until the program turns on focus reporting and the
        /// terminal reports a focus loss.
        var isFocused = true
        var focusChangedAt: Date?
        var lastResize: Date?
    }

    private static let focusIn: [UInt8] = [0x1B, 0x5B, 0x49]   // ESC [ I
    private static let focusOut: [UInt8] = [0x1B, 0x5B, 0x4F]  // ESC [ O

    private let state = OSAllocatedUnfairLock(initialState: State())

    /// Bytes on their way to the shell: a focus report, pointer movement,
    /// or input.
    func noteSent(_ bytes: ArraySlice<UInt8>, at time: Date = Date()) {
        if bytes.elementsEqual(Self.focusIn) {
            noteFocus(true, at: time)
        } else if bytes.elementsEqual(Self.focusOut) {
            noteFocus(false, at: time)
        } else if !Self.isPassiveMouseReport(bytes), !Self.isTerminalReply(bytes) {
            noteInput(at: time)
        }
    }

    /// A reply the terminal generates, never a key: DCS (`ESC P`), OSC
    /// (`ESC ]`), APC (`ESC _`), or a CSI with a `?`/`>` marker ending in
    /// `c` (DA), `u` (kitty flags), `y` (DECRPM) or `n` (DSR), or ending in
    /// `t` (window report). Keys send `ESC [ ? …` / `ESC [ > …` never, and
    /// kitty key events (`CSI 99;5u`) carry no marker.
    static func isTerminalReply(_ bytes: ArraySlice<UInt8>) -> Bool {
        let b = Array(bytes)
        guard b.count >= 3, b[0] == 0x1B else { return false }
        switch b[1] {
        case 0x50, 0x5D, 0x5F:                              // P ] _
            return true
        case 0x5B:                                          // [
            guard let last = b.last else { return false }
            if last == 0x74 { return true }                 // t
            let marked = b[2] == 0x3F || b[2] == 0x3E       // ? >
            return marked && [0x63, 0x75, 0x79, 0x6E].contains(last)   // c u y n
        default:
            return false
        }
    }

    /// A mouse report for motion or the wheel: SGR `ESC [ < b ; x ; y M|m`
    /// or legacy `ESC [ M b x y` (b offset by 32), where bit 32 of the
    /// button code means motion and bit 64 the wheel.
    static func isPassiveMouseReport(_ bytes: ArraySlice<UInt8>) -> Bool {
        let b = Array(bytes)
        guard b.count >= 6, b[0] == 0x1B, b[1] == 0x5B else { return false }
        let code: Int
        if b[2] == 0x3C {                                  // "<": SGR
            guard let last = b.last, last == 0x4D || last == 0x6D,
                  let semicolon = b.firstIndex(of: 0x3B), semicolon > 3,
                  let value = Int(String(decoding: b[3..<semicolon], as: UTF8.self))
            else { return false }
            code = value
        } else if b[2] == 0x4D, b.count == 6 {             // "M": legacy X10
            code = Int(b[3]) - 32
        } else {
            return false
        }
        return code & 32 != 0 || code & 64 != 0
    }

    func noteInput(at time: Date = Date()) {
        state.withLock { $0.lastInput = time }
    }

    func noteFocus(_ focused: Bool, at time: Date = Date()) {
        state.withLock { state in
            guard state.isFocused != focused else { return }
            state.isFocused = focused
            state.focusChangedAt = time
        }
    }

    /// The terminal changed size (SIGWINCH on its way to the program).
    func noteResize(at time: Date = Date()) {
        state.withLock { $0.lastResize = time }
    }

    func noteOutput(at time: Date = Date()) {
        state.withLock { state in
            if let input = state.lastInput, time.timeIntervalSince(input) < Self.echoWindow { return }
            if let resize = state.lastResize, time.timeIntervalSince(resize) < Self.resizeWindow { return }
            state.outputTimes.append(time)
            if state.outputTimes.count > Self.capacity {
                state.outputTimes.removeFirst(state.outputTimes.count - Self.capacity)
            }
        }
    }

    func snapshot() -> TerminalActivitySnapshot {
        state.withLock {
            TerminalActivitySnapshot(
                lastInput: $0.lastInput,
                outputTimes: $0.outputTimes,
                isFocused: $0.isFocused,
                focusChangedAt: $0.focusChangedAt,
                lastResize: $0.lastResize
            )
        }
    }
}
